// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import {
  BrowserChrome,
  DemoStage,
  DockHeader,
  MockPage,
  Toggle,
  type Build,
} from '@/app/demos/stage'

import { CAPTIONS, TARGETS } from './script'

const PANEL_WIDTH = 210
const TIP_WIDTH = 196
const PAGE_RIGHT = 520 - PANEL_WIDTH

const build: Build = ({ tl, q, pos, step, final, move, click, scramble, wait, cursorOut }) => {
  const hover = (index: number) => {
    const target = TARGETS[index]
    const point = pos(target.d, target.ax, 0.5)
    move(target.d, { ax: target.ax, duration: 0.7 })
    tl.to(
      q('tip'),
      {
        x: Math.min(point.x + 12, PAGE_RIGHT - TIP_WIDTH - 6),
        y: point.y + 14,
        opacity: 1,
        duration: 0.7,
        ease: 'power3.inOut',
      },
      '<',
    )
    tl.to(q(target.d), { outlineColor: 'rgba(244,114,182,0.7)', duration: 0.2 }, '>-0.2')
    scramble('tip-text', target.tip, { at: '<', duration: 0.5, chars: '0123456789' })
    if (index > 0)
      tl.to(q(TARGETS[index - 1].d), { outlineColor: 'rgba(244,114,182,0)', duration: 0.2 }, '<')
  }

  tl.set(
    TARGETS.map((target) => q(target.d)),
    { outline: '1px dashed rgba(244,114,182,0)', outlineOffset: 2 },
    0,
  )

  step(0)
  move('switch', { at: 0.2 })
  click('switch')
  tl.to(q('switch-fill'), { opacity: 1, duration: 0.2 }, '<')
  tl.to(q('switch-knob'), { x: 12, duration: 0.25, ease: 'back.out(2)' }, '<')
  tl.to(
    q('status'),
    { text: { value: 'On · hover text on the page', delimiter: '' }, duration: 0.3 },
    '<',
  )

  step(1, '+=0.3')
  hover(0)

  step(2, '+=1')
  hover(1)

  step(3, '+=1')
  hover(2)
  tl.to(q('tip'), { opacity: 0, duration: 0.3 }, '+=1.2')
  tl.to(q(TARGETS[2].d), { outlineColor: 'rgba(244,114,182,0)', duration: 0.2 }, '<')
  cursorOut('<')
  final()
  wait(0.8)
}

export default function Demo() {
  return (
    <DemoStage
      label="Font Inspector showing the computed font family, size, weight and line height of a heading, body copy and a button"
      steps={CAPTIONS}
      build={build}
    >
      <BrowserChrome
        url="https://northwind.app"
        panelWidth={PANEL_WIDTH}
        panel={
          <div className="flex h-full flex-col">
            <DockHeader />
            <div className="p-2.5">
              <div className="flex items-center justify-between gap-2 rounded-xl border border-line bg-white/[0.03] p-3">
                <div>
                  <p className="text-[11px] font-semibold text-ink">Font inspector</p>
                  <p className="mt-0.5 text-[9.5px] leading-snug text-muted">
                    Hover text on the page to inspect typography.
                  </p>
                </div>
                <Toggle d="switch" />
              </div>
              <p data-d="status" className="mt-2 h-3 text-[9px] text-[var(--accent)]" />
            </div>
          </div>
        }
      >
        <MockPage variant="landing" />
      </BrowserChrome>
      <div
        data-d="tip"
        className="pointer-events-none absolute left-0 top-0 z-30 w-[196px] rounded-md bg-black/80 px-2 py-1.5 text-[10px] leading-[1.35] text-white opacity-0 shadow-xl"
      >
        <span data-d="tip-text" />
      </div>
    </DemoStage>
  )
}
